  if (metadata.agentId !== agent.nativeThreadId || metadata.runtime !== "local" ||
    NodePath.resolve(metadata.cwd) !== NodePath.resolve(session.cwd) ||
    NodePath.resolve(metadata.homeDirectory) !== NodePath.resolve(userHome))
    return yield* new ProviderAdapter.ProviderAdapterProtocolError({
      driver: CURSOR_DRIVER_KIND, detail: "Cursor SDK native identity, directory or Home mismatch." });
