const current = yield* Ref.get(liveAgent);
const opened = (probed === current ? probed : null) ?? (yield* openAgent({
  operation: "create", threadId: threadInput.threadId,
  modelSelection: threadInput.modelSelection, runtimePolicy: threadInput.runtimePolicy,
