  return yield* new ProviderAdapter.ProviderAdapterProtocolError({
    driver: CURSOR_DRIVER_KIND, detail: "Cursor SDK resumed a different native session." });
const metadata = yield* readNativeMetadata(agent);

...(metadata?.runs.some(run => run.status === "finished") &&
  metadata.runs.every(run => ["finished", "error", "cancelled"].includes(run.status)) ? {
  nativeHistory: { nativeSessionId: requestedAgentId,
    completedTurnRefs: metadata.runs.filter(run => run.status === "finished").map(run => ({
      driver: CURSOR_DRIVER_KIND, nativeId: run.id, strength: "strong" as const,
