  }))),
  readLegacy: ({ nativeSessionId, turnId, messageId, ensure }) => Effect.gen(function* () {
    const { agent, metadata } = yield* readNative;
    if (metadata.agentId !== nativeSessionId || metadata.runs.some(run => !["finished", "error", "cancelled"].includes(run.status)))
      return yield* new ProviderAdapter.ProviderAdapterProtocolError({ driver: CURSOR_DRIVER_KIND, detail: "Cursor legacy identity is not at a stable boundary." });
    const completed = metadata.runs.filter(run => run.status === "finished");
