      return yield* new ProviderAdapter.ProviderAdapterProtocolError({ driver: CURSOR_DRIVER_KIND, detail: "Cursor legacy completed run was not found." });
    const messages = yield* agent.session.listMessages;
    if (messages.some(message => message.agent_id !== nativeSessionId) ||
      (messageId && messages.at(-1)?.uuid !== messageId))
      return yield* new ProviderAdapter.ProviderAdapterProtocolError({ driver: CURSOR_DRIVER_KIND, detail: "Cursor legacy message boundary changed." });
    const now = yield* DateTime.now;
