      nativeHistory: { nativeSessionId, completedTurnRefs: completed.map(run => ({
        driver: CURSOR_DRIVER_KIND, nativeId: run.id, strength: "strong" as const,
      })) } };
  }),
});
yield* Effect.addFinalizer(() => Effect.sync(unbindEvidence));
